[
	{
		"name": "unlit_color",
		"description": "Simple unlit solid color. For UI, debug, flat-shaded art.",
		"shading_model": "Unlit",
		"parameter_docs": "color(vec4), intensity(scalar), texture_path(string optional — when set, multiplies the texture into the emissive output)"
	},
	{
		"name": "emissive_pulse",
		"description": "Pulsing emissive glow. For crystals, power cores, lights.",
		"shading_model": "Unlit",
		"parameter_docs": "color_bright(vec4), color_dim(vec4), pulse_speed(scalar), intensity(scalar), texture_path(string optional — when set, multiplies the texture into the pulsing emissive output)"
	},
	{
		"name": "panning_texture",
		"description": "Scrolling texture for water, lava, conveyors, energy flows.",
		"shading_model": "Unlit",
		"parameter_docs": "speed_x(scalar), speed_y(scalar), tint_color(vec4), tiling_x(scalar), tiling_y(scalar), texture_path(string), intensity(scalar)"
	},
	{
		"name": "fresnel_glow",
		"description": "Edge-lit Fresnel glow. For shields, auras, rim lighting.",
		"shading_model": "Unlit",
		"parameter_docs": "glow_color(vec4), exponent(scalar), intensity(scalar), base_opacity(scalar), texture_path(string optional — when set, multiplies the texture into the fresnel-tinted emissive output)"
	},
	{
		"name": "dissolve",
		"description": "Dissolve/burn effect. For death, teleportation, materializing.",
		"shading_model": "Unlit",
		"parameter_docs": "dissolve_amount(scalar 0-1), edge_color(vec4), edge_width(scalar), edge_intensity(scalar), noise_scale(scalar), base_color(vec4), texture_path(string optional — when set, multiplies the texture into the base_color portion of the emissive output; the edge-glow is left untextured so it always reads as a glowing ring)"
	},
	{
		"name": "hologram",
		"description": "Holographic scanlines with flicker and spatial noise. For holograms, AR, sci-fi.",
		"shading_model": "Unlit",
		"parameter_docs": "holo_color(vec4), scanline_density(scalar default 0.5), scanline_speed(scalar default 1), flicker_speed(scalar default 1), flicker_scale(scalar default 5 — grain frequency: 0=none, higher=finer grain), fresnel_power(scalar default 5), opacity(scalar default 0.3)"
	},
	{
		"name": "glass",
		"description": "Translucent glass with refraction. For windows, ice, gems.",
		"shading_model": "DefaultLit",
		"parameter_docs": "tint_color(vec4), opacity(scalar), roughness(scalar), metallic(scalar), refraction(scalar)"
	},
	{
		"name": "pbr_standard",
		"description": "Full PBR with all standard params. For realistic objects.",
		"shading_model": "DefaultLit",
		"parameter_docs": "base_color(vec4), metallic(scalar), roughness(scalar), specular(scalar), emissive_color(vec4), emissive_intensity(scalar), texture_path(string), normal_path(string), tiling(scalar default 1.0)"
	},
	{
		"name": "force_field",
		"description": "Animated force field/shield. For energy barriers.",
		"shading_model": "Unlit",
		"parameter_docs": "field_color(vec4), hex_scale(scalar), pulse_speed(scalar), fresnel_power(scalar), intensity(scalar), opacity(scalar), texture_path(string optional), spin_speed(scalar default 0)"
	},
	{
		"name": "gradient",
		"description": "World-space color gradient. For sky domes, terrain.",
		"shading_model": "Unlit",
		"parameter_docs": "color_bottom(vec4), color_top(vec4), gradient_height(scalar), gradient_offset(scalar), intensity(scalar)"
	},
	{
		"name": "toon_shading",
		"description": "Cel/cartoon stepped shading. For anime/cartoon games.",
		"shading_model": "Unlit",
		"parameter_docs": "lit_color(vec4 default white), shadow_color(vec4 default dark grey 0.08), steps(scalar default 4), shadow_threshold(scalar default 0.3), texture_path(string optional), light_direction(vec3 optional — overrides scene directional light if set)"
	},
	{
		"name": "wireframe",
		"description": "Grid/wireframe overlay. For debug, holograms, tech.",
		"shading_model": "Unlit",
		"parameter_docs": "wire_color(vec4), wire_thickness(scalar), grid_scale(scalar), intensity(scalar), base_opacity(scalar)"
	},
	{
		"name": "pbr_metal",
		"description": "Physically-based metallic material. For polished metals, chrome, steel.",
		"shading_model": "DefaultLit",
		"parameter_docs": "base_color(vec4 default silver), roughness(scalar 0-1 default 0.2), texture_path(string optional), normal_path(string optional), tiling(scalar default 1.0)"
	},
	{
		"name": "pbr_wood",
		"description": "Physically-based wood material. For timber, planks, furniture.",
		"shading_model": "DefaultLit",
		"parameter_docs": "base_color(vec4 default warm brown), roughness(scalar 0-1 default 0.75), texture_path(string optional), normal_path(string optional), tiling(scalar default 1.0)"
	},
	{
		"name": "pbr_stone",
		"description": "Physically-based stone material. For rock, concrete, masonry.",
		"shading_model": "DefaultLit",
		"parameter_docs": "base_color(vec4 default grey), roughness(scalar 0-1 default 0.85), texture_path(string optional), normal_path(string optional), tiling(scalar default 1.0)"
	},
	{
		"name": "pbr_plastic",
		"description": "Physically-based plastic material. For smooth plastic, polymer surfaces.",
		"shading_model": "DefaultLit",
		"parameter_docs": "base_color(vec4 default white), roughness(scalar 0-1 default 0.4), texture_path(string optional), normal_path(string optional), tiling(scalar default 1.0)"
	},
	{
		"name": "landscape",
		"description": "Multi-layer weight-blended landscape material. For terrain with paintable layers (grass, rock, dirt). Creates one LandscapeLayerBlend for BaseColor and a parallel one for Roughness so each layer has its own surface finish.",
		"shading_model": "DefaultLit",
		"parameter_docs": "layer_count(int default 3 — supported range 2-16, 2-8 typical, >8 may impact shader performance), layer_names(string[] default [\"Grass\",\"Rock\",\"Dirt\"]), layer_textures(string[] optional — one /Game/ or Saved/ texture path per layer; assigned to Layer{i}_Color), layer_roughnesses(float[] optional — one roughness value per layer 0-1; unspecified layers fall back to default_roughness), default_roughness(scalar default 0.8 — fallback for layers not covered by layer_roughnesses), tiling(scalar default 4.0)"
	},
	{
		"name": "water",
		"description": "Animated translucent water with depth fade, dual panning normals, refraction, and wave animation.",
		"shading_model": "DefaultLit",
		"parameter_docs": "water_color(vec4), deep_color(vec4), depth_fade_distance(scalar default 200), wave_speed(scalar default 0.03), wave_height(scalar default 10), refraction_strength(scalar default 1.05), opacity(scalar default 0.7), roughness(scalar default 0.15)"
	},
	{
		"name": "subsurface",
		"description": "Subsurface scattering material. For skin, wax, jade, candles.",
		"shading_model": "Subsurface",
		"parameter_docs": "base_color(vec4), subsurface_color(vec4 default reddish), roughness(scalar default 0.5), opacity(scalar default 0.8), texture_path(string optional)"
	},
	{
		"name": "decal",
		"description": "Deferred decal material. For projected splatter, footprints, graffiti.",
		"shading_model": "DefaultLit",
		"parameter_docs": "decal_color(vec4 default white), opacity(scalar default 1.0), texture_path(string optional)"
	},
	{
		"name": "masked_foliage",
		"description": "Two-sided foliage material with subsurface transmission. For leaves, grass, vegetation.",
		"shading_model": "TwoSidedFoliage",
		"parameter_docs": "base_color(vec4 default green), subsurface_color(vec4 default bright green), opacity_mask_clip(scalar default 0.33), texture_path(string optional), roughness(scalar default 0.7)"
	},
	{
		"name": "lava",
		"description": "Animated emissive lava material with dual-panning flow and glow.",
		"shading_model": "Unlit",
		"parameter_docs": "lava_color(vec4 default orange-red), glow_intensity(scalar default 5.0), flow_speed(scalar default 0.05), texture_path(string optional)"
	}
]
